import test from 'node:test';import assert from 'node:assert/strict';import {Element} from './helpers/panel-dom.js';import {savedRehearsalGuideFixtures,gate,until} from './helpers/workspace-fixtures.js';import {prepareWalletSavedSourceBundle,reviewWalletSavedBundle,encodeWalletSavedBundleReview} from '../src/file-read-status.js';import {mountSavedBundleReceiptCheckPanel} from '../examples/file-read-panel.js';
async function setup(options={}){const source=savedRehearsalGuideFixtures()[0].text,receipt=await reviewWalletSavedBundle((await prepareWalletSavedSourceBundle(source,source)).text),text=encodeWalletSavedBundleReview(receipt),parent=new Element('div'),document={createElement:tag=>new Element(tag)},downloads=[];let expected=receipt,action=()=>{};const panel=mountSavedBundleReceiptCheckPanel({parent,document,getExpected:()=>expected,download:value=>{downloads.push(value);action();},...options}),q=name=>parent.find('saved-bundle-receipt-check-'+name);return{panel,q,text,downloads,replace(value=null){expected=value;panel.updateExpected();},callback(fn){action=fn;},choose(value=text){q('file').files=[new File([value],'receipt.json')];q('file').dispatchEvent(new Event('change'));},done:()=>until(()=>!panel.getState().busy),save(){q('ack').checked=true;q('ack').dispatchEvent(new Event('change'));q('save').click();}};}
test('saved bundle receipt checking requires its own acknowledgement and saves mismatches with no source values',async()=>{
 const f=await setup();try{f.choose();await f.done();assert(f.panel.getState().result.matchesRecomputation);assert(f.q('save').disabled);f.save();assert.equal(f.downloads.length,1);assert.equal(f.downloads[0].containsOriginalEvidence,false);assert.doesNotMatch(f.downloads[0].text,/0x[0-9a-f]{40}/);assert(f.q('save').disabled);const altered=JSON.parse(f.text);altered.authenticated=true;f.choose(JSON.stringify(altered));await f.done();assert.equal(f.panel.getState().result.matchesRecomputation,false);f.save();assert.deepEqual(JSON.parse(f.downloads.at(-1).text).differences,['authenticated']);f.replace();assert(f.q('file').disabled);assert(f.q('save').disabled);assert.equal(f.q('output').textContent,'');}finally{f.panel.dispose();}
});
for(const action of['stop','replace','dispose'])test('receipt '+action+' clears pending work before late reading completes',async()=>{
 const blocked=gate();let reads=0;const f=await setup({readText(file,options){reads++;assert.equal(options.maxBytes,262144);return blocked.promise;}});try{f.choose();await until(()=>reads===1);if(action==='stop')f.q('stop').click();else if(action==='replace')f.replace();else f.panel.dispose();assert.equal(f.panel.getState().busy,false);blocked.resolve(f.text);await new Promise(resolve=>setTimeout(resolve,0));assert.equal(f.panel.getState().result,null);}finally{blocked.resolve(f.text);f.panel.dispose();}
});
test('invalid replacement and a source change during export cannot retain or publish old success',async()=>{
 const f=await setup();try{f.choose();await f.done();f.callback(()=>f.replace());f.save();assert.doesNotMatch(f.q('status').textContent,/保存処理を開始/);assert.equal(f.panel.getState().result,null);}finally{f.panel.dispose();}
 const g=await setup();try{g.choose();await g.done();g.choose('{}');await g.done();assert.equal(g.panel.getState().result,null);assert(g.q('save').disabled);assert.match(g.q('status').textContent,/確認できません/);}finally{g.panel.dispose();}
});
